// Перечень видов v2 — единственный законный источник для кода: вид, которого
// здесь нет, не существует (ТЗ-BACKEND §2.6). Слой и сцена рождения нужны
// сторожам: видимость по сцене и запрет зависимостей вверх по слоям.
package orbita.kernel.schema

/** Слой модели данных: L0 — полки, L5 — выпуск. */
enum class Layer { L0, L1, L2, L3, L4, L5 }

/**
 * Вид сущности v2.
 *
 * @property code машинный код вида — им же названа схема в schemas/v2
 * @property title имя вида по-русски: интерфейс показывает его, не код
 * @property layer слой; зависимости идут только вниз
 * @property bornIn сцена рождения; null — сущность полки, у неё сцены нет
 * @property statusModel статусная модель, если у вида она есть
 */
data class KindSpec(
    val code: String,
    val title: String,
    val layer: Layer,
    val bornIn: String?,
    val statusModel: String?,
    val requiredFields: List<String>,
    /** Все поля вида по истине YAML — правка на месте отбивает поле вне схемы (З-03). */
    val fields: List<String> = emptyList(),
    /**
     * Поля, которые по истине схем суть ОДНА ссылка на факт (`ref fact`).
     * Их подставляет система: основание сущности она знает сама. Поля с
     * составным источником (перечень ссылок у требования, файл у задания
     * разбора) сюда не входят — туда код факта писать нельзя.
     */
    val factRefFields: List<String> = emptyList(),
    /**
     * Перечни вида по истине схем: поле → допустимые значения.
     * Ими проверяется ввод и ответ службы; девятой копии перечня в
     * коде быть не должно — она разойдётся с истиной молча.
     */
    val enums: Map<String, List<String>> = emptyMap(),
    /**
     * Поля-величины вида: им значение и единица приходят ПАРОЙ
     * («measure{op,value|min,max,unit→unit}»), а не двумя плоскими
     * полями. Имя поля знает истина схем — не код, который пару кладёт.
     */
    val measures: List<String> = emptyList(),
    /**
     * Русское имя поля (`label` истины схем). Экран показывает ТОЛЬКО
     * его: код поля на экране запрещён правилом владельца
     * (`field_rules.label`, 18.09) — человек не обязан знать наши коды.
     */
    val labels: Map<String, String> = emptyMap(),
    /**
     * Стадия, к которой поле обязано быть заполнено (`required_at`):
     * `accept` — при приёме предложения, `baseline` — к базированию,
     * `SRR` и прочие — к точке. Суффиксы говорят, кто и чем заполняет:
     * `system` · `default(x)` · `from_basis` · `auto` · `tbd_allowed` ·
     * `proposed`. Форма приёма спрашивает ровно то, что названо `accept`
     * и не подставляется само (журнал ПМИ-7, З-09).
     */
    val requiredAt: Map<String, String> = emptyMap(),
    /**
     * Примечание поля словами истины: «обязателен для performance» у
     * показателя, «TBD допустим до SRR» у метода. Экран показывает его
     * рядом с полем — иначе необязательное поле выглядит долгом.
     */
    val notes: Map<String, String> = emptyMap(),
)

