        "stakeholder.role" to mapOf("customer" to "заказчик", "regulator" to "регулятор", "operator" to "оператор", "consumer" to "потребитель", "supplier" to "поставщик", "partner" to "партнёр", "established" to "учреждаемый"),
        "state_machine.states.kind" to mapOf("mode" to "режим", "state" to "состояние"),
        "state_machine.transitions.trigger" to mapOf("exchange" to "обмен", "event" to "событие", "timer" to "таймер"),
    )

    /**
     * Операторы величины: код записи → знак для экрана. Схема знает
     * только эти коды («>=»), а человек читает знак («≥»).
     */
    val measureOps: Map<String, String> = mapOf(
        "=" to "=",
        ">=" to "≥",
        "<=" to "≤",
        ">" to ">",
        "<" to "<",
        "~" to "≈",
    )

    val byCode: Map<String, KindSpec> = all.associateBy { it.code }

    /** Вид вне перечня не существует: отказ вместо тихого пропуска. */
    fun of(code: String): KindSpec = byCode[code]
        ?: error("вид «$code» не описан в СХЕМЫ-ПОЛЕЙ-V2.yaml — вид вне истины схем не существует")
}
